<div class="row g-4 mb-4"><div class="col-lg-6"><section class="card h-100"><div class="card-body"><h2 class="h4">Transferir entre contas</h2><p class="small text-secondary">A operação atualiza as duas contas sem criar receita ou despesa.</p><form method="post" action="<?= H::escape($basePath.'/carteira/transferir') ?>" class="row g-3"><?= H::fields($csrfToken) ?>
<?php foreach(['origem_id'=>'Conta de origem','destino_id'=>'Conta de destino'] as $key=>$name): ?><div class="col-md-6"><label class="form-label" for="<?= $key ?>"><?= $name ?></label><select id="<?= $key ?>" name="<?= $key ?>" class="form-select" required><option value="">Selecione</option><?php foreach($accounts as $a): ?><option value="<?= (int)$a['id'] ?>" <?= (int)($old[$key] ?? 0)===(int)$a['id'] ? 'selected' : '' ?>><?= H::escape($a['nome']) ?></option><?php endforeach; ?></select></div><?php endforeach; ?>
