<div class="col-lg-6"><section class="card h-100"><div class="card-body"><h2 class="h4">Conferir saldo de hoje</h2><p class="small text-secondary">Compare com o banco. A diferença será registrada como ajuste, com o motivo informado, sem alterar receitas e despesas.</p><form method="post" action="<?= H::escape($basePath.'/carteira/conferir') ?>" class="row g-3" data-confirm="Registrar a conferência? Uma diferença de saldo gerará um ajuste no histórico."><?= H::fields($csrfToken) ?><div class="col-md-6"><label class="form-label" for="reconcile-account">Conta</label><select id="reconcile-account" name="conta_id" class="form-select" required><option value="">Selecione</option><?php foreach($accounts as $a): ?><option value="<?= (int)$a['id'] ?>"><?= H::escape($a['nome']) ?> · <?= Money::format((int)$a['saldo_atual_centavos']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label" for="reconcile-balance">Saldo no banco (R$)</label><input id="reconcile-balance" name="saldo" class="form-control" inputmode="decimal" required value="<?= H::escape($old['saldo'] ?? '') ?>" placeholder="Aceita saldo negativo"></div><div class="col-12"><label class="form-label" for="reconcile-reason">Motivo / observação</label><input id="reconcile-reason" name="motivo" class="form-control" maxlength="200" required value="<?= H::escape($old['motivo'] ?? '') ?>"></div><div class="col-12"><button class="btn btn-outline-secondary">Registrar conferência</button></div></form></div></section></div></div>
<section class="card"><div class="card-body"><div class="section-heading"><h2 class="h4">Histórico de caixa</h2><form method="get" class="d-flex gap-2"><label class="visually-hidden" for="statement-account">Conta do extrato</label><select id="statement-account" name="conta" class="form-select"><?php foreach($accounts as $a): ?><option value="<?= (int)$a['id'] ?>" <?= (int)($account['id'] ?? 0)===(int)$a['id'] ? 'selected' : '' ?>><?= H::escape($a['nome']) ?></option><?php endforeach; ?></select><button class="btn btn-outline-secondary">Ver</button></form></div>
<?php if ($account): ?><p class="text-secondary">Saldo inicial em <?= H::date($account['saldo_inicial_em']) ?>: <?= Money::format((int)$account['saldo_inicial_centavos']) ?> · Saldo atual: <strong><?= Money::format((int)$account['saldo_atual_centavos']) ?></strong></p><?php endif; ?>
<div class="table-responsive"><table class="table"><thead><tr><th>Data</th><th>Descrição</th><th>Origem</th><th class="text-end">Entrada / saída</th></tr></thead><tbody><?php foreach(array_slice($entries,0,50) as $entry): ?><tr><td><?= H::date($entry['data']) ?></td><td><?= H::escape($entry['descricao']) ?></td><td><?= H::escape($entry['origem']) ?></td><td class="text-end <?= $entry['valor_centavos']<0 ? '' : 'text-success' ?>"><?= Money::format((int)$entry['valor_centavos']) ?></td></tr><?php endforeach; ?><?php if (!$entries): ?><tr><td colspan="4" class="py-4 text-secondary">Nenhuma movimentação de caixa nesta conta.</td></tr><?php endif; ?></tbody></table></div><div class="d-flex gap-3"><?php if($page>1): ?><a href="<?= H::escape($basePath.'/carteira?conta='.($account['id'] ?? 0).'&pagina='.($page-1)) ?>">← Anterior</a><?php endif; ?><span>Página <?= $page ?></span><?php if(count($entries)>50): ?><a href="<?= H::escape($basePath.'/carteira?conta='.($account['id'] ?? 0).'&pagina='.($page+1)) ?>">Próxima →</a><?php endif; ?></div></div></section>
